import numpy as np
from sklearn.metrics.pairwise import cosine_similarity

from app.analyzers.base import BaseAnalyzer
from app.models import (
    AnalysisResult,
    DatasetConfig,
    Finding,
)


class LabelValidationAnalyzer(BaseAnalyzer):

    @property
    def name(self) -> str:
        return "label_validation"

    def analyze(
        self,
        working_dataset,
        config: DatasetConfig,
    ) -> AnalysisResult:

        # Label validation is performed separately
        # using embeddings generated by EmbeddingPipeline.

        return AnalysisResult(
            analyzer=self.name,
            images_checked=0,
            findings=[],
        )

    def process_embeddings(
        self,
        embeddings: np.ndarray,
        image_ids: list[str],
        labels: list[str | None],
        config: DatasetConfig,
    ) -> AnalysisResult:

        # -----------------------------------------
        # 1. Check whether label validation is ON
        # -----------------------------------------

        if not config.enable_label_validation:

            return AnalysisResult(
                analyzer=self.name,
                images_checked=len(image_ids),
                findings=[],
            )

        # -----------------------------------------
        # 2. Validate input
        # -----------------------------------------

        if len(embeddings) == 0:

            return AnalysisResult(
                analyzer=self.name,
                images_checked=0,
                findings=[],
            )

        if not (
            len(embeddings)
            == len(image_ids)
            == len(labels)
        ):

            raise ValueError(
                "Embeddings, image IDs, and labels "
                "must have the same length."
            )

        # -----------------------------------------
        # 3. Group labeled images by class
        # -----------------------------------------

        label_indices: dict[str, list[int]] = {}

        for index, label in enumerate(labels):

            if label is None:
                continue

            label_indices.setdefault(
                label,
                [],
            ).append(index)

        # We need at least two classes.
        if len(label_indices) < 2:

            return AnalysisResult(
                analyzer=self.name,
                images_checked=len(image_ids),
                findings=[],
            )

        findings = []

        # -----------------------------------------
        # 4. Validate each labeled image
        # -----------------------------------------

        for index, label in enumerate(labels):

            if label is None:
                continue

            own_indices = [
                i
                for i in label_indices[label]
                if i != index
            ]

            # Cannot validate a class containing
            # only one image.
            if not own_indices:
                continue

            # -----------------------------------------
            # Similarity to own class
            # -----------------------------------------

            own_embeddings = embeddings[
                own_indices
            ]

            own_similarities = cosine_similarity(
                embeddings[index].reshape(1, -1),
                own_embeddings,
            )[0]

            own_similarity = float(
                np.mean(own_similarities)
            )

            # -----------------------------------------
            # Find the best alternative class
            # -----------------------------------------

            best_label = label
            best_similarity = own_similarity

            for other_label, indices in (
                label_indices.items()
            ):

                if other_label == label:
                    continue

                other_embeddings = embeddings[
                    indices
                ]

                similarities = cosine_similarity(
                    embeddings[index].reshape(1, -1),
                    other_embeddings,
                )[0]

                similarity = float(
                    np.mean(similarities)
                )

                if similarity > best_similarity:

                    best_similarity = similarity
                    best_label = other_label

            # -----------------------------------------
            # Debug information
            # -----------------------------------------

            print(
                f"[LABEL CHECK] "
                f"{image_ids[index]} | "
                f"current={label} | "
                f"own_similarity="
                f"{own_similarity:.4f} | "
                f"best_label={best_label} | "
                f"best_similarity="
                f"{best_similarity:.4f}"
            )

            # -----------------------------------------
            # Wrong label
            # -----------------------------------------

            wrong_label = (
                best_label != label
                and
                best_similarity
                >
                own_similarity
                + config.label_margin
            )

            if wrong_label:

                findings.append(
                    Finding(
                        image_id=image_ids[index],
                        issue_type="wrong_label",
                        severity="high",
                        reason=(
                            f"Image is labeled "
                            f"'{label}', but is more "
                            f"similar to the "
                            f"'{best_label}' class."
                        ),
                        value=best_similarity,
                        threshold=config.label_margin,
                    )
                )

                continue

            # -----------------------------------------
            # Suspicious label
            # -----------------------------------------

            low_similarity = (
                own_similarity
                <
                config.label_similarity_threshold
            )

            if low_similarity:

                findings.append(
                    Finding(
                        image_id=image_ids[index],
                        issue_type="suspicious_label",
                        severity="medium",
                        reason=(
                            f"Image has low visual "
                            f"similarity to other "
                            f"'{label}' images."
                        ),
                        value=own_similarity,
                        threshold=(
                            config.label_similarity_threshold
                        ),
                    )
                )

        # -----------------------------------------
        # 5. Return result
        # -----------------------------------------

        return AnalysisResult(
            analyzer=self.name,
            images_checked=len(image_ids),
            findings=findings,
        )